reference_solution:
def gas_station_start(gas, cost):
    total = tank = start = 0
    for index, (fuel, expense) in enumerate(zip(gas, cost)):
        delta = fuel - expense
        total += delta
        tank += delta
        if tank < 0:
            start = index + 1
            tank = 0
    return start if total >= 0 else -1

